<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="utf-8">
<title>Billiards</title>
<style>
* { margin:0; padding:0; box-sizing:border-box; }
body {
  background:#0c0c0c;
  display:flex; flex-direction:column; align-items:center; justify-content:center;
  min-height:100vh; font-family:Arial,sans-serif; user-select:none;
}
canvas { display:block; cursor:crosshair; max-width:100vw;
  box-shadow:0 12px 48px rgba(0,0,0,.95),0 0 0 3px #4a2808; }
#hud { margin-top:14px; display:flex; flex-direction:column; align-items:center; gap:8px; }
button {
  background:linear-gradient(135deg,#8b6020,#5a3808); color:#f0d080;
  border:1px solid #c89020; padding:9px 30px; border-radius:5px;
  cursor:pointer; font-size:14px; font-weight:bold; letter-spacing:1px; text-transform:uppercase;
}
button:hover { background:linear-gradient(135deg,#aa7830,#7a4818); }
#info { color:#888; font-size:13px; text-align:center; max-width:640px; line-height:1.6; }
#info strong { color:#c8a050; }
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="hud">
  <button id="resetBtn">&#8635; Reset / Rack</button>
  <div id="info">
    <strong>HOW TO SHOOT:</strong>
    Click &amp; drag <em>back</em> from the white ball to aim &middot; release to strike &middot; longer drag = more power
  </div>
</div>
<script>
/* ── config ── */
const RAIL   = 48;
const PW     = 840;
const PH     = 420;
const CW     = PW + 2*RAIL;
const CH     = PH + 2*RAIL;
const R      = 13;
const DECEL  = 108;
const WALL_E = 0.72;
const MAX_V  = 1800;
const POCK_R = R * 1.45;

const POCKETS = [
  {x:0,    y:0},   {x:PW/2, y:0},   {x:PW,   y:0},
  {x:0,    y:PH},  {x:PW/2, y:PH},  {x:PW,   y:PH},
];

const PAL = [
  '#cccccc','#f7c518','#1560bd','#c8102e','#6a0dad',
  '#ff6600','#007a33','#8b1a1a','#101010',
];

/* ── canvas ── */
const canvas = document.getElementById('c');
canvas.width = CW; canvas.height = CH;
const ctx = canvas.getContext('2d');

let balls = [], paused = false, animId = null, lastTs = null;
let dragActive = false, mouseX = 0, mouseY = 0;

const toC = v => v + RAIL;

/* ── physics ── */
function advance(dt) {
  for (const b of balls) {
    if (b.potted) continue;
    b.x += b.vx * dt;
    b.y += b.vy * dt;
    const spd = Math.hypot(b.vx, b.vy);
    if (spd > 0) {
      const ns = Math.max(0, spd - DECEL*dt);
      b.vx = b.vx*ns/spd; b.vy = b.vy*ns/spd;
    }
    if (b.x < R)      { b.x = R;      b.vx =  Math.abs(b.vx)*WALL_E; }
    if (b.x > PW-R)   { b.x = PW-R;   b.vx = -Math.abs(b.vx)*WALL_E; }
    if (b.y < R)      { b.y = R;      b.vy =  Math.abs(b.vy)*WALL_E; }
    if (b.y > PH-R)   { b.y = PH-R;   b.vy = -Math.abs(b.vy)*WALL_E; }
  }
  for (let i = 0; i < balls.length; i++) {
    if (balls[i].potted) continue;
    for (let j = i+1; j < balls.length; j++) {
      if (balls[j].potted) continue;
      resolveCollision(balls[i], balls[j]);
    }
  }
  for (const b of balls) {
    if (b.potted) continue;
    for (const p of POCKETS) {
      if (Math.hypot(b.x-p.x, b.y-p.y) < POCK_R) {
        b.potted = true; b.vx = b.vy = 0; break;
      }
    }
  }
}

function resolveCollision(a, b) {
  const dx = b.x-a.x, dy = b.y-a.y, d = Math.hypot(dx, dy);
  if (d >= 2*R || d < 1e-9) return;
  const nx = dx/d, ny = dy/d;
  const pen = (2*R-d)*0.5;
  a.x -= nx*pen; a.y -= ny*pen;
  b.x += nx*pen; b.y += ny*pen;
  const van = a.vx*nx + a.vy*ny;
  const vbn = b.vx*nx + b.vy*ny;
  if (van <= vbn) return;
  const dv = van-vbn;
  a.vx -= dv*nx; a.vy -= dv*ny;
  b.vx += dv*nx; b.vy += dv*ny;
}

/* ── rendering ── */
function shiftHex(hex, amt) {
  const r = Math.max(0,Math.min(255,parseInt(hex.slice(1,3),16)+amt));
  const g = Math.max(0,Math.min(255,parseInt(hex.slice(3,5),16)+amt));
  const b = Math.max(0,Math.min(255,parseInt(hex.slice(5,7),16)+amt));
  return `rgb(${r},${g},${b})`;
}

function drawTable() {
  ctx.fillStyle = '#1e0c02';
  ctx.fillRect(0, 0, CW, CH);

  const rg = ctx.createLinearGradient(0,0,CW,CH);
  rg.addColorStop(0,'#a07035'); rg.addColorStop(0.4,'#c89040');
  rg.addColorStop(0.6,'#9a6828'); rg.addColorStop(1,'#704518');
  ctx.fillStyle = rg;
  ctx.fillRect(4,4,CW-8,CH-8);

  ctx.fillStyle = '#0a0a0a';
  for (const p of POCKETS) {
    ctx.beginPath(); ctx.arc(toC(p.x),toC(p.y),POCK_R+7,0,Math.PI*2); ctx.fill();
  }

  const fg = ctx.createRadialGradient(toC(PW/2),toC(PH/2),20,toC(PW/2),toC(PH/2),PW*0.68);
  fg.addColorStop(0,'#2e8c2e'); fg.addColorStop(1,'#195819');
  ctx.fillStyle = fg;
  ctx.fillRect(RAIL,RAIL,PW,PH);

  ctx.strokeStyle='rgba(0,0,0,.5)'; ctx.lineWidth=5;
  ctx.strokeRect(RAIL+2,RAIL+2,PW-4,PH-4);
  ctx.strokeStyle='rgba(80,170,80,.18)'; ctx.lineWidth=2;
  ctx.strokeRect(RAIL+7,RAIL+7,PW-14,PH-14);

  for (const p of POCKETS) {
    const px=toC(p.x), py=toC(p.y);
    const pg = ctx.createRadialGradient(px,py,0,px,py,POCK_R+5);
    pg.addColorStop(0,'#050505'); pg.addColorStop(0.7,'#0d0d0d'); pg.addColorStop(1,'rgba(8,8,8,0)');
    ctx.fillStyle=pg; ctx.beginPath(); ctx.arc(px,py,POCK_R+6,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='#050505'; ctx.beginPath(); ctx.arc(px,py,POCK_R,0,Math.PI*2); ctx.fill();
    ctx.strokeStyle='rgba(180,120,40,.65)'; ctx.lineWidth=1.5;
    ctx.beginPath(); ctx.arc(px,py,POCK_R+0.5,0,Math.PI*2); ctx.stroke();
  }

  ctx.strokeStyle='rgba(220,200,140,.22)'; ctx.lineWidth=1;
  ctx.setLineDash([4,5]);
  ctx.beginPath(); ctx.moveTo(toC(PW*0.25),RAIL+5); ctx.lineTo(toC(PW*0.25),CH-RAIL-5); ctx.stroke();
  ctx.setLineDash([]);

  for (const sx of [PW*0.25, PW*0.5, PW*0.75]) {
    ctx.fillStyle='rgba(220,200,140,.38)';
    ctx.beginPath(); ctx.arc(toC(sx),toC(PH/2),2.8,0,Math.PI*2); ctx.fill();
  }
}

function drawBall(b) {
  const x = toC(b.x), y = toC(b.y);

  ctx.save(); ctx.globalAlpha=0.32; ctx.fillStyle='#000';
  ctx.beginPath(); ctx.ellipse(x+3,y+5,R*0.82,R*0.4,0,0,Math.PI*2); ctx.fill();
  ctx.restore();

  if (b.cue) {
    const g = ctx.createRadialGradient(x-R*.36,y-R*.38,R*.08,x,y,R);
    g.addColorStop(0,'#ffffff'); g.addColorStop(0.62,'#e6e6e6'); g.addColorStop(1,'#b8b8b8');
    ctx.fillStyle=g; ctx.beginPath(); ctx.arc(x,y,R,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='rgba(255,255,255,.7)';
    ctx.beginPath(); ctx.arc(x-R*.3,y-R*.32,R*.18,0,Math.PI*2); ctx.fill();
  } else {
    const num = b._num, isStripe = num>8, ci = isStripe ? num-8 : num;
    const color = PAL[ci]||'#888888';

    if (isStripe) {
      const g = ctx.createRadialGradient(x-R*.3,y-R*.34,R*.1,x,y,R);
      g.addColorStop(0,'#f0f0f0'); g.addColorStop(1,'#c4c4c4');
      ctx.fillStyle=g; ctx.beginPath(); ctx.arc(x,y,R,0,Math.PI*2); ctx.fill();
      ctx.save(); ctx.beginPath(); ctx.arc(x,y,R,0,Math.PI*2); ctx.clip();
      ctx.fillStyle=color; ctx.fillRect(x-R,y-R*.44,R*2,R*.88);
      ctx.restore();
    } else {
      const g = ctx.createRadialGradient(x-R*.32,y-R*.35,R*.08,x,y,R);
      g.addColorStop(0,shiftHex(color,55)); g.addColorStop(0.65,color); g.addColorStop(1,shiftHex(color,-40));
      ctx.fillStyle=g; ctx.beginPath(); ctx.arc(x,y,R,0,Math.PI*2); ctx.fill();
    }

    ctx.fillStyle='white'; ctx.beginPath(); ctx.arc(x,y,R*.44,0,Math.PI*2); ctx.fill();
    ctx.fillStyle='#0a0a0a'; ctx.font=`bold ${Math.floor(R*.72)}px Arial`;
    ctx.textAlign='center'; ctx.textBaseline='middle'; ctx.fillText(num,x,y+.5);
    ctx.fillStyle='rgba(255,255,255,.46)';
    ctx.beginPath(); ctx.arc(x-R*.26,y-R*.3,R*.17,0,Math.PI*2); ctx.fill();
  }

  ctx.strokeStyle='rgba(0,0,0,.28)'; ctx.lineWidth=0.8;
  ctx.beginPath(); ctx.arc(x,y,R,0,Math.PI*2); ctx.stroke();
}

function drawAim() {
  if (!dragActive) return;
  const cb = balls.find(b=>b.cue&&!b.potted);
  if (!cb) return;
  const bx=toC(cb.x), by=toC(cb.y);
  const dx=bx-mouseX, dy=by-mouseY, dist=Math.hypot(dx,dy);
  if (dist<3) return;
  const nx=dx/dist, ny=dy/dist, power=Math.min(dist/160,1);

  ctx.save();
  ctx.strokeStyle='rgba(255,255,180,.46)'; ctx.lineWidth=1.2; ctx.setLineDash([7,6]);
  ctx.beginPath(); ctx.moveTo(bx,by); ctx.lineTo(bx+nx*240,by+ny*240); ctx.stroke();
  ctx.setLineDash([]);

  const tipX=bx-nx*(R+1), tipY=by-ny*(R+1);
  const buttX=mouseX-nx*28, buttY=mouseY-ny*28;
  const sg = ctx.createLinearGradient(tipX,tipY,buttX,buttY);
  sg.addColorStop(0,'#e0d8b0'); sg.addColorStop(0.04,'#c8a040');
  sg.addColorStop(0.6,'#a07828'); sg.addColorStop(1,'#5a3010');
  ctx.strokeStyle=sg; ctx.lineWidth=6; ctx.lineCap='round';
  ctx.beginPath(); ctx.moveTo(tipX,tipY); ctx.lineTo(buttX,buttY); ctx.stroke();

  const gx=12,gy=CH-28,gw=130,gh=14;
  ctx.fillStyle='rgba(0,0,0,.55)'; ctx.fillRect(gx-2,gy-2,gw+4,gh+4);
  ctx.fillStyle='#222'; ctx.fillRect(gx,gy,gw,gh);
  const pr=Math.round(255*power), pg2=Math.round(255*(1-power));
  ctx.fillStyle=`rgb(${pr},${pg2},0)`; ctx.fillRect(gx,gy,Math.round(gw*power),gh);
  ctx.strokeStyle='#666'; ctx.lineWidth=1; ctx.strokeRect(gx,gy,gw,gh);
  ctx.fillStyle='#ccc'; ctx.font='11px Arial';
  ctx.textAlign='left'; ctx.textBaseline='middle';
  ctx.fillText('POWER',gx+gw+6,gy+gh/2);
  ctx.restore();
}

function render() {
  drawTable();
  drawAim();
  for (const b of balls) if (!b.potted) drawBall(b);
}

/* ── animation loop ── */
function loop(ts) {
  if (!paused) {
    if (lastTs !== null) advance(Math.min((ts-lastTs)/1000, 1/30));
    lastTs = ts;
    render();
    animId = requestAnimationFrame(loop);
  }
}

/* ── input ── */
function getPos(e) {
  const rect=canvas.getBoundingClientRect();
  return { cx:(e.clientX-rect.left)*CW/rect.width, cy:(e.clientY-rect.top)*CH/rect.height };
}

canvas.addEventListener('mousedown', e => {
  const {cx,cy}=getPos(e), px=cx-RAIL, py=cy-RAIL;
  const cb=balls.find(b=>b.cue&&!b.potted);
  if (cb && Math.hypot(px-cb.x,py-cb.y)<R*3.5) {
    dragActive=true; mouseX=cx; mouseY=cy;
  }
  e.preventDefault();
},{passive:false});

canvas.addEventListener('mousemove', e => {
  if (!dragActive) return;
  const {cx,cy}=getPos(e); mouseX=cx; mouseY=cy;
  e.preventDefault();
},{passive:false});

canvas.addEventListener('mouseup', e => {
  if (!dragActive) return;
  const {cx,cy}=getPos(e);
  const cb=balls.find(b=>b.cue&&!b.potted);
  if (cb) {
    const bx=toC(cb.x), by=toC(cb.y), dx=bx-cx, dy=by-cy, d=Math.hypot(dx,dy);
    if (d>4) { const p=Math.min(d/160,1)*MAX_V; cb.vx=dx/d*p; cb.vy=dy/d*p; }
  }
  dragActive=false; e.preventDefault();
},{passive:false});

canvas.addEventListener('mouseleave',()=>{ dragActive=false; });

function fakeM(type,t) { canvas.dispatchEvent(new MouseEvent(type,{clientX:t.clientX,clientY:t.clientY})); }
canvas.addEventListener('touchstart', e=>{ e.preventDefault(); fakeM('mousedown',e.touches[0]); },{passive:false});
canvas.addEventListener('touchmove',  e=>{ e.preventDefault(); fakeM('mousemove',e.touches[0]); },{passive:false});
canvas.addEventListener('touchend',   e=>{ e.preventDefault(); fakeM('mouseup',e.changedTouches[0]); },{passive:false});

/* ── rack ── */
function makeRack() {
  const out=[];
  out.push({x:PW*.25,y:PH/2,vx:0,vy:0,cue:true,potted:false,_num:0});
  const footX=PW*.75, footY=PH/2, sp=R*2.02;
  const order=[1,9,2,3,8,10,4,11,5,12,13,6,14,7,15];
  let idx=0;
  for (let row=0;row<5;row++) {
    for (let col=0;col<=row;col++) {
      out.push({
        x: footX + row*sp*(Math.sqrt(3)/2),
        y: footY + (col-row/2)*sp,
        vx:0, vy:0, cue:false, potted:false, _num:order[idx++]
      });
    }
  }
  return out;
}

/* ── window.sim API ── */
window.sim = {
  get W() { return PW; },
  get H() { return PH; },
  get R() { return R;  },

  reset(bs) {
    balls = bs.map((b,i) => ({
      x: b.x, y: b.y,
      vx: b.vx??0, vy: b.vy??0,
      cue: !!b.cue, potted: false,
      _num: b.cue ? 0 : i+1,
    }));
    render();
  },

  step(dt) { advance(dt); render(); },

  state() {
    return balls.map(b => ({x:b.x,y:b.y,vx:b.vx,vy:b.vy,potted:b.potted,cue:b.cue}));
  },

  shoot(vx, vy) {
    const cb=balls.find(b=>b.cue&&!b.potted);
    if (cb) { cb.vx=vx; cb.vy=vy; }
  },

  pause() {
    paused=true;
    if (animId!==null) { cancelAnimationFrame(animId); animId=null; }
    lastTs=null;
  },

  resume() {
    if (!paused) return;
    paused=false; lastTs=null;
    animId=requestAnimationFrame(loop);
  },
};

/* ── boot ── */
document.getElementById('resetBtn').addEventListener('click', () => {
  balls=makeRack(); dragActive=false; render();
});

balls  = makeRack();
animId = requestAnimationFrame(loop);
</script>
</body>
</html>
